package com.emssystem.emsleaveservice.pto.mapper; import com.emssystem.emsleaveservice.pto.dto.response.*; import com.emssystem.emsleaveservice.pto.entity.*;
public final class PtoMapper{private PtoMapper(){} public static PtoTypeResponse toResponse(PtoType t){return new PtoTypeResponse(t.getId(),t.getName(),t.getAccrualRatePerPeriod(),t.getMaxCarryover(),t.isPaid());}public static PtoRequestResponse toResponse(PtoRequest r){return new PtoRequestResponse(r.getId(),r.getEmployeeId(),r.getPtoType().getId(),r.getPtoType().getName(),r.getStartDate(),r.getEndDate(),r.getHours(),r.getStatus(),r.getReviewedBy(),r.getReviewedAt(),r.getCreatedAt(),r.getUpdatedAt());}public static PtoBalanceResponse toResponse(PtoBalance b){return new PtoBalanceResponse(b.getId(),b.getEmployeeId(),b.getPtoType().getId(),b.getPtoType().getName(),b.getAccruedHours(),b.getUsedHours(),b.getReservedHours());}}
